export async function signIn(
    page: Page,
    url: string,
    username: string,
    password: string,
    landingPath = "/login"
) {
    await page.goto(`${url}${landingPath}`);
    await page.getByTestId("username-input").fill(username);
    await page.getByTestId("password-input").fill(password);
    await page.getByTestId("submit-login-button").click();
    // Structural wait: the app has left the sign-in route.
    await page.waitForURL((u) => !u.pathname.startsWith("/login"));
}

export async function applyHighlightColorFilter(page: Page, colorTestId: string) {
    await page.getByTestId(colorTestId).click();
}

export async function searchHighlights(page: Page, term: string) {
    await page.getByTestId("highlight-search").fill(term);
}

export function highlightCard(page: Page, cardText: string) {
    return page.getByTestId("highlight-card").filter({ hasText: cardText });
}

export async function openHighlightNoteEditor(page: Page, cardText: string) {
    await highlightCard(page, cardText).getByTestId("highlight-edit-note").click();
}

export async function saveHighlightNote(page: Page, cardText: string, note: string) {
    const card = highlightCard(page, cardText);
    await card.getByTestId("highlight-note-input").fill(note);
    await card.getByTestId("highlight-note-save").waitFor({ state: "visible" });
    const responsePromise = page.waitForResponse("**/api/v1/highlights/**");
    await card.getByTestId("highlight-note-save").click();
    return await responsePromise;
}
